function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw einstein
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // draw clock
  ctx.beginPath();
  ctx.arc(W/2 + 100, H/2, 30, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2);
  ctx.lineTo(W/2 + 100 + 20 * Math.sin(t), H/2 - 20 * Math.cos(t));
  ctx.stroke();

  // draw space time curvature
  ctx.beginPath();
  ctx.moveTo(0, H/2 + 50 * Math.sin(t));
  ctx.bezierCurveTo(W/2, H/2 + 50 * Math.sin(t + Math.PI/2), W/2, H/2 + 50 * Math.sin(t - Math.PI/2), W, H/2 + 50 * Math.sin(t));
  ctx.stroke();

  ctx.restore();
}
